CGriffin::CGriffin() : CWeaponObject(0),
m_petrifySparkles(NULL)
{
	ISceneNode* brokenGround = LoadColladaScene("Scenes/Griffin/broken_road.bdae");
	__IRR_SCENE()->getRootSceneNode()->addChild(brokenGround);
	cleanNode(brokenGround, false);
	m_brokenGround.setRoot(brokenGround);

	ISceneNode* petrify = LoadColladaScene("Scenes/Griffin/griffin_wave.bdae");
	__IRR_SCENE()->getRootSceneNode()->addChild(petrify);
	cleanNode(petrify, false);
	m_petrifyWave.setRoot(petrify);

	m_Node = LoadColladaScene("Scenes/Griffin/griffin.bdae");
	__IRR_SCENE()->getRootSceneNode()->addChild(m_Node);
	cleanNode(m_Node);
	setEmissiveColor(m_Node, CGameConfig::EmissiveColorForInteractiveObjects * 0.5f);

	m_shadow = LoadColladaScene("Scenes/Goblin/shadow.bdae");
	cleanNode(m_shadow);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_shadow);
	
	setRoot(m_Node);

	m_scaleDummy = m_Node->getSceneNodeFromName("d_transform_bip01");
	m_scaleBip01 = m_Node->getSceneNodeFromUID("Bip01-node");

	m_touch = new CTouchElement(CTouchElement::Type_AnyTouch, 100);
	m_touch->SetScreenCoordinates(280, 32, 95, 140);

	setLevel(WL_None);
	reset();

	m_petrifyCountdown = 0.0f;
}

void CGriffin::setSpawnPosition(vector3df pos)
{
	m_spawnPosition = pos;
	setPosition(pos);
}

void CGriffin::reset()
{
	CWeaponObject::reset();

	if (m_level != WL_None)
	{
		setShouldBeVisible(true, false, false, false);
		setPosition(m_spawnPosition);

		//setState(GGS_Inactive);
		//setAnim("activate");

		setAnim("active");
		setState(GGS_Active);
	}
	else
	{
		setState(GGS_Disabled);
		setShouldBeVisible(false, false, false, false);
	}

	setVisible(true);

	if (m_petrifySparkles)
	{
		RemoveParticleSystem(m_petrifySparkles);
		m_petrifySparkles = 0;
	}

	m_cooldown = 0.0f;
}

CGriffin::~CGriffin ()
{
	m_Node->remove();
	m_Node->drop();

	m_shadow->remove();
	m_shadow->drop();

	m_brokenGround.getRoot()->remove();
	m_brokenGround.getRoot()->drop();

	m_petrifyWave.getRoot()->remove();
	m_petrifyWave.getRoot()->drop();

	if (m_petrifySparkles)
	{
		RemoveParticleSystem(m_petrifySparkles);
		m_petrifySparkles = 0;
	}

	SAFE_DEL(m_touch);
}

void CGriffin::adjustStats(IAttributes* attributes)
{
	const char* cooldown[] = { "CooldownEasy", "CooldownMedium", "CooldownHard" };
	int difficulty = (int)(CPlayfield::GetInstance()->getDifficulty());
	m_stat_cooldown =	attributes->getAttributeAsFloat( cooldown[difficulty] );

	m_stat_radius =		attributes->getAttributeAsFloat("DamageRadius");
	m_stat_hits =		attributes->getAttributeAsInt("Hits");
	m_stat_petrify =	attributes->getAttributeAsFloat("PetrifyTime");

	switch (m_level)
	{
	case WL_1:
		{
			ITexture * tex = __IRR_DRIVER()->getTexture("Scenes/Griffin/griffin_00.png");
			m_Node->getSceneNodeFromName("griffin")->getChildren().getFirstElem()->getMaterial(0).setTexture(0, tex);
			m_Node->getSceneNodeFromName("base00")->setVisible(true);
			m_Node->getSceneNodeFromName("base01")->setVisible(false);
			m_Node->getSceneNodeFromName("base02")->setVisible(false);
		}
		break;

	case WL_2:
		{
			ITexture * tex = __IRR_DRIVER()->getTexture("Scenes/Griffin/griffin_01.png");
			m_Node->getSceneNodeFromName("griffin")->getChildren().getFirstElem()->getMaterial(0).setTexture(0, tex);
			m_Node->getSceneNodeFromName("base00")->setVisible(false);
			m_Node->getSceneNodeFromName("base01")->setVisible(true);
			m_Node->getSceneNodeFromName("base02")->setVisible(false);
		}
		break;

	case WL_3:
		{
			ITexture * tex = __IRR_DRIVER()->getTexture("Scenes/Griffin/griffin_02.png");
			m_Node->getSceneNodeFromName("griffin")->getChildren().getFirstElem()->getMaterial(0).setTexture(0, tex);
			m_Node->getSceneNodeFromName("base00")->setVisible(false);
			m_Node->getSceneNodeFromName("base01")->setVisible(false);
			m_Node->getSceneNodeFromName("base02")->setVisible(true);
		}
		break;
	}
}

v3f Interpolate (float t, v3f startPos, v3f startVel, v3f endPos, v3f endVel)
{
	v3f d = startPos;
	v3f c = startVel;
	v3f b = 3.0f * (endPos - startPos) - 2.0f * startVel - endVel;
	v3f a = 2.0f * (startPos - endPos) + startVel + endVel;
	return d + t * (c + t * (b + t * a));
}

void CGriffin::update (f32 time)
{
	CWeaponObject::update(time);

	/// Animation Scale for Bip01
	{
		const v3f scale = m_scaleDummy->getScale();
		m_scaleBip01->setScale(scale);
	}

	switch (m_state)
	{
		case GGS_Inactive:
		{
			if (m_cooldown >= 0.0f)
			{
				m_cooldown -= time;
				if (m_cooldown <= 0.0f || CGameConfig::NoWeaponCD)
				{
					m_cooldown = 0.0f;
					activate();
				}
			}
			break;
		}

		case GGS_Active:
		{
			if(checkEvent("scream"))
			{
				CPlayfield::GetInstance()->PlaySfx( SFX_DEFENSE_GRIFFIN_MOVING );
			}

			if (m_touch->IsActive())
			{
				setState(GGS_GoingUp);
				setShouldBeVisible(true, true, m_visibleEffect, m_visiblePetrify);
				setAnimAnim("fly_off", "fly");
				CPlayfield::GetInstance()->StopSfx( SFX_DEFENSE_GRIFFIN_MOVING );
			}
			break;
		}

		case GGS_Up:
		case GGS_GoingUp:
		{
			if (m_touch->IsActive())
			{
				
				if(!__MGR_SOUNDS()->isSoundPlaying( SFX_DEFENSE_GRIFFIN_FLAP ))
					CPlayfield::GetInstance()->PlaySfx( SFX_DEFENSE_GRIFFIN_FLAP, true );

				plane3df pl = CPlayfield::GetInstance()->getFlyingPlane();
				position2di touch;
				m_touch->GetTouchPos_Current(touch.X, touch.Y);

				vector3df newPos;
				line3df ray = __IRR_SCENE()->getSceneCollisionManager()->getRayFromScreenCoordinates(touch);
				pl.getIntersectionWithLine(ray.start, ray.getVector(), newPos);

				plane3df plCastle = CPlayfield::GetInstance()->getCastlePlane();
				plCastle.D -= 2.0f;
				if (plCastle.classifyPointRelation(newPos) != ISREL3D_FRONT)
				{
					plCastle.getIntersectionWithLine(newPos, CPlayfield::GetInstance()->getPath().getVector(), newPos);
				}

				vector3df upPos;
				plane3df plGround = CPlayfield::GetInstance()->getGroundPlane();
				plGround.D -= 4.0f;
				plGround.getIntersectionWithLine(newPos, vector3df(0, 1, 0), upPos);

				position2di touch_delta;
				m_touch->GetTouchPos_DT(touch_delta.X, touch_delta.Y);

				if (m_state == GGS_GoingUp)
				{
					vector3df dir = upPos - getPosition();
					if (dir.getLength() < 1.0f)
					{
						setState(GGS_Up);
						setPosition(upPos);
						if (m_brokenGround.getCurrentAnimIndex() == 0)
							m_brokenGround.setAnim(1, false);
					}
					else
					{
						dir /= time;
						if (dir.getLength() > 40.0f)
							dir.setLength(40.0f);
						setPosition(getPosition() + dir * time);
					}
					break;
				}
				else
				{
					bool boom = false;

					if (float(touch_delta.Y) / time > 600.0f)
					{
						boom = true;
					}

					if (newPos.Y < upPos.Y)
					{
						upPos.Y += 0.2f * (newPos.Y - upPos.Y);
					}

					setPosition(upPos);

					if (boom)
					{
						setState(GGS_Smashing);
						CPlayfield::GetInstance()->getChallenge()->specialWeaponUsed();

						CPlayfield::GetInstance()->StopSfx( SFX_DEFENSE_GRIFFIN_FLAP );
						CPlayfield::GetInstance()->PlaySfx( SFX_DEFENSE_GRIFFIN_SMASH );

						CPlayfield::GetInstance()->getGroundPlane().getIntersectionWithLine(newPos, vector3df(0,1,0), newPos);
						setPosition(newPos);
						m_cooldown += m_stat_cooldown / m_stat_hits;
						
						if (m_stat_petrify > 0)
						{
							setShouldBeVisible(m_visibleObject, m_visibleShadow, m_visibleEffect, true);
							m_petrifyWave.setAnim(0, false);
							m_petrifyWave.getRoot()->setPosition(getPosition());
						}

						ParticleSystem* ps = 0;
						ps = AddParticleSystem("grifon_fall");
						ps->SetScale(0.17f);
						ps->SetPosition(getPosition() - vector3df(0, 0.5f, 0));
						ps->SetRotation(quaternion(0.5f * PI, 0.0f, 0.0f));


						// kill them all!
						int unitsHitByKind[UK_Unknown + 1] = { 0 };

						const TUnitList& units = CPlayfield::GetInstance()->getUnits();
						TUnitList::ConstIterator it = units.begin();
						while (it != units.end())
						{
							CUnit* unit = (*it);
							v3f vec = unit->getAbsolutePosition() - getPosition();
							vec.Y = 0;
							if (vec.getLength() <= m_stat_radius)
							{
								if (unit->isPetrified())
									unit->unpetrify(true);
								else if (unit->getUnitKind() == UK_Elf && RandFloat(0, 1) < 0.9f - 0.1f * m_level)
									unit->elfJump(1.0f);
								else
									unit->damageUnit(9999, UDS_GriffinSmash);
								++unitsHitByKind[unit->getUnitKind()];
							}
							it++;
						}
						m_smashTimer = 0.0f;
						CPlayfield::GetInstance()->getChallenge()->unitsWereKilledByWeapon(UDS_GriffinSmash, unitsHitByKind);

						CPlayfield::GetInstance()->SetCameraShake(0.7f, 1.0f);

						m_brokenGround.setAnim(0, false);
						m_brokenGround.getRoot()->setPosition(getPosition() + v3f(0,1.7,0));
						setShouldBeVisible(true, true, true, m_stat_petrify > 0.0f);

						if (m_stat_petrify > 0.0f)
						{
							petrify();
						}
					}
				}
			}
			else
			{
				CPlayfield::GetInstance()->StopSfx( SFX_DEFENSE_GRIFFIN_FLAP );

				if (m_brokenGround.getCurrentAnimIndex() == 0)
					m_brokenGround.setAnim(1, false);
				flyToSpawnPosition();
			}
			break;
		}

		case GGS_Smashing:
		{
			m_smashTimer += time;
			if (m_smashTimer > 0.7f)
			{
				if (m_cooldown < m_stat_cooldown && m_touch->IsActive())
				{
					setState(GGS_GoingUp);
				}
				else
				{
					if (m_brokenGround.getCurrentAnimIndex() == 0)
						m_brokenGround.setAnim(1, false);
					flyToSpawnPosition();
				}
			}
			break;
		}
		case GGS_FlyingToSpawnPosition:
		{
			m_deactivatingTimer += time;
			float t = m_deactivatingTimer / 0.6f;
			if (t > 1.0f)
			{
				setPosition(m_spawnPosition);
				if (m_cooldown > 0.0f)
				{
					deactivate();
				}
				else
				{
					setPosition(m_spawnPosition);
					setState(GGS_Active);
					setAnim("active");
					setShouldBeVisible(true, false, m_visibleEffect, m_visiblePetrify);
				}
			}
			else
			{
				setPosition(Interpolate(t, m_deactivatingStartPosition, v3f(0, 0, 0), m_spawnPosition, v3f(0, -20, 0)));
			}
			break;
		}

		case GGS_Shop:
			{
			}
			break;
	}

	if (m_state == GGS_GoingUp || m_state == GGS_Up || m_state == GGS_Smashing || m_state == GGS_FlyingToSpawnPosition)
	{
		v3f shadowPos;
		CPlayfield* playfield = CPlayfield::GetInstance();
		playfield->getGroundPlane().getIntersectionWithLine(getPosition(), v3f(0,1,0), shadowPos);
		m_shadow->setPosition(shadowPos);
		float distanceFromGround = playfield->getGroundPlane().getDistanceTo(getPosition());
		float scale = 5.0f - 0.1f * distanceFromGround;
		CLAMP(scale, 0.4f, 5.0f);
		m_shadow->setScale(v3f(scale, scale, scale));
	}

	updatePetrify(time);

	m_brokenGround.updateAtEndOfFrame(time);
	m_petrifyWave.updateAtEndOfFrame(time);
	updateAtEndOfFrame(time);
}

void CGriffin::draw ()
{
}

void CGriffin::setVisible(bool visible)
{
	m_visible = visible;
	m_Node->setVisible(m_visible && m_visibleObject);
	m_shadow->setVisible(m_visible && m_visibleShadow);
	m_brokenGround.getRoot()->setVisible(visible && m_visibleEffect);
	m_petrifyWave.getRoot()->setVisible(visible && m_visiblePetrify);
}

bool CGriffin::isVisible()
{
	return m_visible;
}

void CGriffin::setShouldBeVisible(bool object, bool shadow, bool effect, bool petrify)
{
	m_visibleObject = object;
	m_visibleShadow = shadow;
	m_visibleEffect = effect;
	m_visiblePetrify = petrify;
	setVisible(m_visible);
}

void CGriffin::activate ()
{
	setAnimAnim(strcmp(getCurrentAnimName(), "freeze") == 0 ? "freeze_to_idle" : "activate", "active");
	setState(GGS_Active);

	//if( CPlayfield::GetInstance()->GetDayTime() > 0.1f )
	//	CPlayfield::GetInstance()->PlaySfx( SFX_DEFENSE_GRIFFIN_MOVING );
}

void CGriffin::deactivate ()
{
	setAnimAnim("unactivate", "unactive");
	setState(GGS_Inactive);
	setPosition(m_spawnPosition);
	setShouldBeVisible(true, false, m_visibleEffect, m_visiblePetrify);
}

float CGriffin::getCooldown ()
{
	if (m_state != GGS_Inactive)
		return 0.0f;

	return m_cooldown / m_stat_cooldown;
}

void CGriffin::setState(GriffinState state)
{
	m_state = state;
}

GriffinState CGriffin::getState ()
{
	return (GriffinState)m_state;
}

CTouchElement* CGriffin::getTouch ()
{
	return m_touch;
}

void CGriffin::elfArrowHit ()
{
	if (m_state == GGS_Active)
	{
		m_cooldown += m_stat_cooldown;
		deactivate();
		setAnim("freeze", false);

		CPlayfield::GetInstance()->PlaySfx( SFX_ATTACK_SABOTAGE_WEAPON );
	}
}

void CGriffin::setShopState()
{
	setShouldBeVisible(true, false, false, false);
	m_touch->SetEnabled(false);

	setAnim("idle");
	setState(GGS_Shop);
}

void CGriffin::flyToSpawnPosition ()
{
	if (m_cooldown > 0.0f)
		m_cooldown = m_stat_cooldown;
	m_deactivatingTimer = 0.0f;
	m_deactivatingStartPosition = getPosition();
	setState(GGS_FlyingToSpawnPosition);
}

void CGriffin::petrify()
{
	m_petrifyCountdown = 0.25f;
	m_petrifyPosition = getPosition();
}

void CGriffin::updatePetrify(f32 time)
{
	if (m_petrifyWave.checkEvent("anim_end"))
		setShouldBeVisible(m_visibleObject, m_visibleShadow, m_visibleEffect, false);

	if (m_petrifyCountdown > 0.0f)
	{
		m_petrifyCountdown -= time;

		if (m_petrifyCountdown <= 0.0f)
		{
			petrifyBlast();
		}
	}

	if (m_petrifySparklesTime > 0.0f)
	{
		m_petrifySparklesTime -= time;

		if (m_petrifySparklesTime <= 0.0f)
		{
			RemoveParticleSystem(m_petrifySparkles);
			m_petrifySparkles = NULL;
		}
	}

}

void CGriffin::petrifyBlast()
{
	if (!m_petrifySparkles)
	{
		m_petrifySparkles = AddParticleSystem("sparkles");
		line3df path = CPlayfield::GetInstance()->getPath();
		v3f pos = path.start + path.getVector() * 0.6f;
		m_petrifySparkles->SetPosition(pos);
		m_petrifySparkles->SetRotation(quaternion(0.5f * PI, 0.0f, 0.0f));
		m_petrifySparkles->SetScale(0.17f);
	}

	m_petrifySparklesTime = m_stat_petrify;

	bool petrifiedUnit = false;

	// petrify all
	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	TUnitList::ConstIterator it = units.begin();
	while (it != units.end())
	{
		CUnit* unit = (*it);
		v3f vec = unit->getAbsolutePosition() - getPosition();
		vec.Y = 0;
		if (unit->canBePetrified() && vec.getLength() < 7.0f)
		{
			petrifiedUnit = true;
			unit->petrify(m_stat_petrify, true);
		}
		it++;
	}

	if (petrifiedUnit)
		CPlayfield::GetInstance()->PlaySfx( SFX_DEFENCE_GRIFFIN_PETRIFICATION );
}
